# ---------------------------------------------------------------- Beyond: areas between curves
d.sec('8.z-area-between-curves')
b('Area between two curves y = f(x) (upper) and y = g(x) (lower) from x = a to b?', T('A = ∫ₐᵇ [f(x) − g(x)] dx') + '. Find a and b as the x-coordinates where the curves meet. If they cross, split there')
sm.area_between_parabolas(d)
b('Area between y = x and y = x²?', 'Meet at 0 and 1: ∫₀¹ (x − x²) dx = 1/2 − 1/3 = ' + N('1/6'))
