b('Area of the segment of the parabola y² = 4ax cut off by its latus rectum x = a?', '2 ∫₀ᵃ 2√(ax) dx = 4√a · (2/3) a^(3/2) = ' + N('8a²/3'))
b('Area between y² = 4ax and x² = 4ay?', N('16a²/3') + ' (4 × 4 case: 16/3)')
b('Area between y = sin x and y = cos x from x = 0 to π/4?', '∫₀^(π/4) (cos x − sin x) dx = [sin x + cos x]₀^(π/4) = √2 − 1: ' + N('√2 − 1'))
b('Area between y = sin x and y = cos x between two successive intersections (π/4 to 5π/4)?', '∫ (sin x − cos x) dx = [−cos x − sin x] = 2√2: ' + N('2√2'))
b('Area under y = |x| from x = −1 to 2?', 'Triangle 1/2 plus triangle 2: ' + N('5/2'))
b('Area under y = eˣ from 0 to 1, and under y = 1/x from 1 to e?', N('e − 1') + ' and ' + N('1'))
b('Area of a triangle with vertices (0, 0), (2, 0), (2, 3) by integration?', 'The hypotenuse is y = 3x/2: ∫₀² (3x/2) dx = ' + N('3'))
b('Area of the region enclosed by the circle x² + y² = 4 and the line x + y = 2 (smaller part)?', 'Quarter circle minus triangle: π − 2. ' + N('π − 2'))
b('Area between y = x² and y = |x|?', 'By symmetry 2 ∫₀¹ (x − x²) dx = ' + N('1/3'))

